"""generate_keys_and_assets.py: 全書 28 章 112 幅幾何向量圖繪製清冊 (完美順序版)"""

def get_figure_catalog():
    return [('Fig 1.1', '割線斜率逼近與切線極限定義圖', '笛卡兒坐標系', '曲線 $y=f(x)$，割線割於 $P(x_0, y_0)$ 與 $Q(x_0+\\Delta x, y_0+\\Delta y)$，動態箭頭展示 $\\Delta x \\to 0$ 時割線旋轉貼合為切線。'), ('Fig 1.2', '高階無窮小幾何矩形面積壓縮圖', '二維微元幾何', '寬度為 $\\Delta x$，高度為 $\\Delta x$ 的小正方形面積 $(\\Delta x)^2$，對比寬度為 $\\Delta x$、高為 1 的矩形，展示高階小量在面積意義上的微縮消融。'), ('Fig 1.3', '局部仿射線性逼近與切線局部貼合圖', '笛卡兒局部放大', '在切點鄰域作顯微鏡式同心圓放大，展示非線性曲線在極小微元內與直線切線完全重合的仿射幾何本質。'), ('Fig 1.4', '自由落體運動 $s-t$ 拋物線與瞬時速度斜率圖', '運動學坐標系', '縱軸位移 $s$，橫軸時間 $t$；展示割線平均速度 $\\bar{v}$ 與切線瞬時速度 $v(t) = gt$ 的斜率演繹。'), ('Fig 2.1', '二項式展開之 $n$ 維超立方體微元切割圖', '高維幾何投影', '邊長為 $x+\\Delta x$ 的正方形或立方體，分割出主體 $x^n$、$n$ 個厚度為 $\\Delta x$ 的面片微元 $n x^{n-1}\\Delta x$ 以及邊角高階微元。'), ('Fig 2.2', '多項式一階導數與二階導數三線對齊降階圖', '多坐標縱向對齊', "頂部 $y=x^3-3x$、中部一階導數拋物線 $y'=3x^2-3$、底部二階導數直線 $y''=6x$，三圖垂直對齊，極值點對應零點，拐點對應極值。"), ('Fig 2.3', '庫侖勢能曲線 $V(r) \\propto 1/r$ 與保守力負梯度圖', '勢能幾何', '橫軸距離 $r$，縱軸電勢能 $V$；在任意點作切線，其負斜率指向力方向 $F = -\\mathrm{d}V/\\mathrm{d}r$。'), ('Fig 2.4', '反函數幾何對稱軸 $y=x$ 切線斜率倒數投影圖', '對稱解析幾何', '原函數 $y=f(x)$ 與反函數 $x=f^{-1}(y)$ 關於直線 $y=x$ 對稱，兩切線在對稱點的斜率互為倒數 $m_1 m_2 = 1$。'), ('Fig 3.1', '拋物線割線穿透 vs 切線相切之幾何重根圖', '解析幾何相切', '直線與二次拋物線聯立，割線有兩個不同交點，平移至切線處兩交點合流為二重切點。'), ('Fig 3.2', '差函數 $D(x) = f(x) - L(x)$ 在切點處二重根貼地圖', '代數差函數', '展示差函數曲線在 $x_0$ 處值為零且切線水平（橫軸），局部呈現二次拋物線頂點形態 $(x-x_0)^2$。'), ('Fig 3.3', '三次曲線拐點切線穿越圖（三重根幾何穿透）', '奇異穿透幾何', '函數 $y=x^3$ 在原點處，差函數為 $x^3$，在原點兩側變號穿透橫軸，展示三重根幾何特徵。'), ('Fig 3.4', '拋物面鏡平行入射光線經切線法線反射聚焦圖', '幾何光學反射', '平行於對稱軸的光線射向拋物線每一點，作局部幾何切線與法線，精確展示反射角等於入射角且全部匯聚於焦點 $(0, f)$。'), ('Fig 4.1', '傳動齒輪嚙合角速度比率與連鎖律幾何圖', '機械傳動模型', '三個齒輪 $x, u, y$ 互相嚙合，展示周邊線速度相等時角位移變化率連乘 $\\frac{\\mathrm{d}y}{\\mathrm{d}x} = \\frac{\\mathrm{d}y}{\\mathrm{d}u}\\frac{\\mathrm{d}u}{\\mathrm{d}x}$。'), ('Fig 4.2', '球體體積微元薄球殼膨脹幾何圖', '立體幾何微元', '半徑為 $r$ 的實心球體，外側包裹厚度為 $\\mathrm{d}r$ 的薄球殼，體積增量微元展開為表面積乘厚度 $\\mathrm{d}V = 4\\pi r^2 \\mathrm{d}r$。'), ('Fig 4.3', '相關變化率滑梯靠牆滑落速度向量三角形', '幾何運動學', '長度為 $L$ 的梯子，底端水平速度 $\\dot{x}$ 與頂端下滑速度 $\\dot{y}$ 通過勾股定理 $x^2+y^2=L^2$ 微商連鎖耦合。'), ('Fig 4.4', '多層折射介質光線傳播斯涅爾連乘齒輪圖', '波動幾何', '光線連續穿過多層介質，層間角度連鎖微商滿足 $n_1\\sin\\theta_1 = n_2\\sin\\theta_2 = \\dots$。'), ('Fig 5.1', '圓與橢圓隱函數切線向量與梯度正交圖', '隱函數幾何', '橢圓方程 $x^2/a^2 + y^2/b^2 = 1$ 曲線，切線方向向量與法向梯度向量 $\\nabla F$ 保持正交，展示不解出 $y$ 的微分本質。'), ('Fig 5.2', '笛卡兒葉形線幾何奇異自相交點微商極限圖', '代數幾何曲線', '葉形線 $x^3+y^3-3axy=0$ 在原點處自交，作動態割線極限，展示隱函數微分如何分別提取出水平與垂直兩條切線。'), ('Fig 5.3', '大氣等壓線切線與地轉風向量偏轉幾何圖', '地球物理場', '氣壓場標量等值線，梯度力指向垂直切線方向，科氏力偏轉使風向平行於等壓切線。'), ('Fig 5.4', '熱力學相圖氣液共存曲線克拉伯龍方程幾何圖', '相變物理', 'P-T 相圖共存曲線，隱函數切線斜率 $\\mathrm{d}P/\\mathrm{d}T$ 對應相變潛熱與體積變化比值。'), ('Fig 6.1', '運動學 $(x, v)$ 相平面拋物線軌道幾何圖', '相空間運動學', '橫軸位移 $x$，縱軸速度 $v$；勻加速運動軌跡 $v^2-v_0^2 = 2as$ 為拋物線，微商斜率等於 $a/v$。'), ('Fig 6.2', '重力下落速度隨位移變化相軌跡幾何圖', '相軌道分析', '自由落體相軌道 $v = \\sqrt{2gx}$，展示微元面積與相變換動線。'), ('Fig 6.3', '垂直上拋運動相空間閉合半橢圓軌道圖', '相平面封閉性', '上升與下降過程在 $(x, v)$ 平面構成對稱閉合回線，展示時間反演對稱性。'), ('Fig 6.4', '彈簧振子保守系統相平面標準正橢圓軌跡圖', '相空間能量積分', '橫軸位移 $x$，縱軸 $v/\\omega$；封閉圓軌道半徑等於振幅，軌道面積直接對應系統機械能守恆。'), ('Fig 7.1', '單位圓扇形、三角幾何與弦長夾擠極限定理圖', '單位圓幾何', '展示 $\\sin\\theta < \\theta < \\tan\\theta$，三者面積幾何夾擠，當 $\\theta \\to 0$ 時極限逼近為 1。'), ('Fig 7.2', '弧度無量綱化弧長微元 $\\mathrm{d}s = r\\,\\mathrm{d}\\theta$ 幾何圖', '弧度定義微元', '展示半徑與弧長同量綱相除消除單位，微元弧長純數展開。'), ('Fig 7.3', '正弦曲線切線斜率動態旋轉投射為餘弦圖', '導數動態映射', '正弦函數頂點斜率為 0，過原點斜率為 1，切線斜率值動態勾勒出餘弦曲線。'), ('Fig 7.4', '圓周運動在兩正交軸上的投影簡諧波形圖', '幾何投影對偶', '旋轉質點在 x、y 軸上的正交投影分別對應正弦與餘弦時間序列。'), ('Fig 8.1', '極坐標系動態基底向量 $\\hat{e}_r, \\hat{e}_\\theta$ 旋轉微商圖', '極坐標微分幾何', '基底向量隨角度旋轉，展示 $\\mathrm{d}\\hat{e}_r/\\mathrm{d}t = \\dot{\\theta}\\hat{e}_\\theta$ 與 $\\mathrm{d}\\hat{e}_\\theta/\\mathrm{d}t = -\\dot{\\theta}\\hat{e}_r$。'), ('Fig 8.2', '勻速圓周運動速度微元 $\\Delta \\vec{v}$ 指向圓心圖', '向量差微元', '相鄰兩時刻速度向量平移至同一點，向量差 $\\Delta \\vec{v}$ 垂直於速度指向圓心，推導向心加速度 $v^2/r$。'), ('Fig 8.3', '開普勒行星運動橢圓軌道掠面速度守恆幾何圖', '角動量幾何', '微元三角形面積 $\\mathrm{d}A = \\frac{1}{2}r^2\\,\\mathrm{d}\\theta$，時間導數常數對應開普勒第二定律。'), ('Fig 8.4', '天體圓軌道引力提供向心力平方反比微商圖', '引力動力學', '萬有引力 $G M m / r^2$ 等於向心力 $m v^2 / r$，導出開普勒第三定律 $r^3 \\propto T^2$。'), ('Fig 9.1', '光在兩介質交界面傳播總時間極值曲線圖', '費馬變分幾何', '折射點位置為變數 $x$，總傳播時間 $t(x)$ 在極值點導函數為零，嚴格導出斯涅爾折射定律。'), ('Fig 9.2', '光線在平滑曲面反射極值路徑與鏡像等價幾何圖', '幾何光學極值', '反射光程對比圖，展示入射角等於反射角時時間最短。'), ('Fig 9.3', '大氣漸變折射率介質中光線連續彎曲泛函極值圖', '連續介質變分', '大氣密度梯度導致折射率隨高度變化，光線路徑微元積分極值化表現為海市蜃樓彎曲。'), ('Fig 9.4', '【最小作用量原理思想前哨】光程時間極值與力學軌道極值對偶圖', '變分法思想源頭', '展示費馬時間極值 $\\delta t = 0$ 與力學最小作用量 $\\delta S = 0$ 的哲學同構性，為 Ch 19 拉格朗日密技埋下深遠伏筆。'), ('Fig 10.1', '黎曼和區間均勻分割矩形逼近曲邊梯形面積圖', '黎曼和定義', '區間 $[a, b]$ 分割為 $n$ 份，小矩形階梯覆蓋，展示 $n \\to \\infty$ 時誤差鋸齒收縮為零。'), ('Fig 10.2', '左端點、右端點與中點黎曼和上凸下凹誤差對比圖', '數值微積分幾何', '中點法矩形面積誤差正負相消，展示黎曼和收斂速率。'), ('Fig 10.3', '阿基米德拋物線弓形面積無窮幾何級數割補圖', '古希臘窮竭法', '內接三角形幾何級數公比 $1/4$，無窮求和得出拋物線面積 $4/3$ 倍內接三角形。'), ('Fig 10.4', '不規則變截面立體體積積分薄片疊加圖', '立體幾何微元', '沿軸線厚度為 $\\mathrm{d}x$ 的薄片微元體積 $\\mathrm{d}V = A(x)\\,\\mathrm{d}x$，累加求積。'), ('Fig 11.1', '變上限積分函數 $F(x) = \\int_a^x f(t)\\,\\mathrm{d}t$ 面積增量圖', 'FTC 幾何證明', "展示當上限增加 $\\Delta x$ 時，面積增量為薄矩形 $f(x)\\Delta x$，兩端除以 $\\Delta x$ 取極限定出 $F'(x) = f(x)$。"), ('Fig 11.2', '微分算子與積分算子互為逆運算對稱鏡像圖', '算子代數幾何', '變化率之網與積聚之面積互相抵消的合流圖解。'), ('Fig 11.3', '速度曲線時間定積分等於位移淨增量圖', '運動學 FTC 映射', '$v-t$ 曲線下方帶符號面積，正面積為正向位移，負面積為反向位移，總代數和等於淨位置變化。'), ('Fig 11.4', '功率曲線時間定積分等於能量累積圖', '功率能量對偶', '瞬時功率 $P(t)$ 曲線時間積分等於機械能或電能累積總功。'), ('Fig 12.1', '均勻平面薄板第一面積矩與形心坐標微元圖', '質量幾何矩', '微元面片位置加權積分 $\\int x\\,\\mathrm{d}A$，形心即面積支撐平衡點。'), ('Fig 12.2', '拋物線曲邊梯形形心定位定積分幾何分割圖', '解析形心計算', '函數 $y = x^2$ 下方面積微元計算形心 $\\bar{x} = 3/4 b$。'), ('Fig 12.3', '帕普斯第一與第二旋轉體定理幾何軌跡圖', '旋轉幾何定理', '平面曲線旋轉一週表面積等於弧長乘形心路徑；平面區域旋轉體積等於面積乘形心路徑。'), ('Fig 12.4', '非均勻密度細棒質心積分與力矩天平平衡圖', '質心力矩平衡', '線性密度棒 $\\lambda(x) = k x$，微元重力力矩定積分完全抵消於質心支點。'), ('Fig 13.1', '換元積分法幾何面積橫軸尺度伸縮扭曲圖', '換元幾何映射', "自變量變換 $x = g(u)$，橫軸區間伸縮微元 $\\mathrm{d}x = g'(u)\\,\\mathrm{d}u$，面積保持不變。"), ('Fig 13.2', '分部積分法二維矩形面積拆解幾何對偶圖', '分部積分幾何', '矩形頂角處 $\\mathrm{d}(uv) = u\\,\\mathrm{d}v + v\\,\\mathrm{d}u$，展示 $\\int u\\,\\mathrm{d}v$ 與 $\\int v\\,\\mathrm{d}u$ 拼滿矩形 $uv$。'), ('Fig 13.3', '變力做功曲線下方陰影面積與動能轉化圖', '保守力做功', '力隨位置變化 $F(x)$，曲線下方定積分面積等於質點動能增量。'), ('Fig 13.4', '分子作用勢能 Lennard-Jones 曲線與微振盪勢阱圖', '化學勢能微積分', '分子間斥力與引力平衡點附近拋物線勢阱微元展開。'), ('Fig 14.1', '雙曲線 y=1/t 下方面積定義自然對數幾何圖', '幾何微積分定義', '橫軸 t，縱軸 1/t；[1, x] 區間下方的陰影面積嚴格定義 ln(x)，展示冪法則奇異點的面積拯救。'), ('Fig 14.2', '定積分換元法證明對數加法性 ln(ab)=ln(a)+ln(b) 幾何圖', '幾何面積切片變換', '[1, ab] 區間被拆為 [1, a] 與 [a, ab]，利用換元法 t = a u 證明第二塊面積恰好等於 [1, b] 區間面積。'), ('Fig 14.3', '自指指數函數 y=e^x 切線斜率等於縱坐標幾何圖', '微分幾何切線', '指數函數曲線任意點 (x, e^x)，其切線底邊投影次切線長恆等於 1，斜率恆等於縱坐標 y。'), ('Fig 14.4', '連續複利極限柱狀增長逼近自然常數 e 幾何圖', '離散到連續極限', '一年分期計息次數 n 自 1、2、12 增長至無窮大，複利累積柱狀高度漸近收斂於 e=2.71828...。'), ('Fig 15.1', '高爾頓板釘板滾珠下落二項分佈累積直方圖', '物理幾何模型', '鋼珠穿過多層交錯排列釘板，每排向左向右機率各半，底部漏斗槽內鋼珠堆疊出離散階梯直方圖。'), ('Fig 15.2', '直方圖柱寬 Delta x 坍縮為連續鐘形曲線極限圖', '極限定義幾何', '展示柱寬 Delta x 趨於 0 時，離散柱狀階梯頂部平滑化為連續機率密度曲線 f(x)，柱高轉化為機率密度。'), ('Fig 15.3', '連續型單點機率為零與區間定積分面積對比圖', '微元面積圖', '展示 x=c 處一條無寬度的直線幾何測度為零，對比 [a, b] 區間下方定積分陰影面積代表區間機率。'), ('Fig 15.4', '標準鐘形曲線與黑板待償 sqrt(2pi) 懸念記帳圖', '概念伏筆圖', '標準高斯曲線輪廓，標註頂點高度 1/(sqrt(2pi) sigma) 與待多變數微積分清償的數學帳單標籤。'), ('Fig 16.1', '一階微分方程斜率場（Slope Field）與積分曲線族圖', '微分方程幾何解', '二維平面上密佈表示導數 dy/dt 的短線段切線場，展示初值條件如何挑選出一條唯一平滑解軌道。'), ('Fig 16.2', '線性空氣阻力下落速度漸近曲線與終端速度極限圖', '運動學漸近曲線', '速度 v(t) 自原點以斜率 g 啟動，逐漸彎折漸近於水平漸近線 v_term = mg/k。'), ('Fig 16.3', '牛頓冷卻定律溫度對數衰減曲線族圖', '熱力學動態衰減', '不同初始溫度的物體在同一環境溫度下的散熱曲線，展示溫差按指數衰減 e^{-kt} 的幾何規律。'), ('Fig 16.4', '化學反應一級 vs 二級動力學濃度衰減特徵對比圖', '化學反應相圖', '一級反應半衰期恆定（等比衰減），二級反應 1/[A] 隨時間線性上升，對照兩類微分方程本質。'), ('Fig 17.1', '連續介質流管微元質量流率控制體柱狀幾何圖', '流體動力學控制體', '流體流經斷面 A，時間 dt 內流出長度為 v dt 的微元圓柱體，質量 dm = rho A v dt，衝力 F = v(dm/dt)。'), ('Fig 17.2', '高壓水槍射流垂直衝擊平板動量流轉向分流圖', '動量通量幾何', '水流垂直射向剛性平板後沿切向分散，法向動量在撞擊面完全損失，形成穩定衝擊力 F = rho A v^2。'), ('Fig 17.3', '齊奧爾科夫斯基火箭噴氣推力控制體動量反衝圖', '變質量系統力學', '火箭本體質量 m 隨燃料噴出微元 dm 減小，噴氣相對速度 u 產生前進反衝推力。'), ('Fig 17.4', '雷射光子束撞擊完全吸收 vs 完全反射鏡動量反彈雙倍光壓圖', '近代光壓幾何', '左側完全吸收動量變化 Delta p = p_photon；右側完全反射 Delta p = 2 p_photon，光壓翻倍幾何示意。'), ('Fig 18.1', 'RC 電路充電電荷 q(t) 與放電電流 i(t) 互補指數曲線圖', '暫態電路響應', '電荷 q 向上凸漸近於 C E，電流 i 向下凹衰減於 0，標註時間常數 tau 處 63.2% 與 36.8% 特徵點。'), ('Fig 18.2', 'RL 電路通電電流增長與電感反電動勢突變衰減圖', '電磁暫態曲線', '電流緩慢上升至 E/R，電感感應電動勢在接通瞬間達到峰值 E，隨後按指數規律退化為 0。'), ('Fig 18.3', 'RC 充電 50% 能量分配直方柱狀對比圖', '能量分佈對比', '電池輸出功 C E^2，精確拆分為電容儲能 1/2 C E^2 與電阻焦耳熱 1/2 C E^2 兩等高柱狀圖。'), ('Fig 18.4', '電阻瞬間熱耗散功率曲線 P_R(t) 與最大功率峰值幾何圖', '瞬時功率定積分', '電阻功率隨時間先增後減，在 t = tau ln 2 處達到最大峰值，曲線下方總面積收斂於 1/2 C E^2。'), ('Fig 19.1', '簡諧運動位移、速度、加速度三線縱向對齊相圖', '運動學導函數對齊', '頂部 x(t) = A cos(omega t)，中部速度 v(t) 相位超前 90 度，底部加速度 a(t) 與位移完全反相 180 度。'), ('Fig 19.2', '簡諧運動相空間 (x, v) 閉合正橢圓軌道與能量守恆圖', '相空間封閉軌道', '橫軸位移 x，縱軸速度 v/omega；封閉橢圓周長軌道代表機械能守恆，面積正比於作用量。'), ('Fig 19.3', '阻尼振盪三種狀態（欠阻尼、臨界阻尼、過阻尼）位移軌跡對比圖', '二階系統動力學', '欠阻尼呈現指數包絡線振盪，臨界阻尼最快平穩回歸原點，過阻尼遲緩回歸。'), ('Fig 19.4', '【拉格朗日量神級密技】小車單擺耦合系統廣義坐標與免受力圖自動生成二階 ODE 圖', '分析力學黑魔法', '左圖展示牛頓法複雜受力分解，右圖展示 L = T - V 尤拉-拉格朗日方程 3 行自動輸出運動微分方程對比。'), ('Fig 20.1', 'P-V 圖上等溫線 vs 絕熱線斜率陡峭度對比圖', '熱力學相平面', '同一狀態點 (P_0, V_0) 處，等溫線斜率 -P/V 與絕熱線斜率 -gamma P/V，展示絕熱線的陡峭微商特徵。'), ('Fig 20.2', '氣體膨脹做功微元 dW = P dV 陰影面積圖', '微元做功幾何', 'P-V 曲線下方垂直條帶微元 P dV，等溫過程展開為雙曲線下方面積 nRT ln(V_2/V_1)。'), ('Fig 20.3', '絕熱過程分離變數法溫度-體積微分關係圖', '狀態微分軌道', '展示 dQ = 0 時內能減小與做功相消，dT/T 與 (gamma-1) dV/V 的反向等比例收縮。'), ('Fig 20.4', '卡諾熱機循環四段微積分做功閉合四邊形圖', '熱機循環幾何', '兩條等溫線與兩條絕熱線圍成的封閉幾何曲邊四邊形，淨做功面積即熱機效率來源。'), ('Fig 21.1', '三位一體狀態空間 (p, v)、(q, V)、(Phi, i) 三角形面積並列圖', '相空間幾何對偶', '三個並列坐標系，分別展示動能 int v dp、電容能 int V dq、電感能 int i dPhi 下方三角形面積 1/2。'), ('Fig 21.2', '光子極端相對論做功相空間水平線矩形對比圖', '相對論相空間', '光子速度恆為 c，做功微元 dE = c dp，相空間軌跡為水平直線，定積分面積為矩形 E = pc（無 1/2）。'), ('Fig 21.3', '平行板電容器充能電荷微元 dq 與電壓階梯圖', '電磁做功幾何', '橫軸電荷 q，縱軸電壓 V=q/C；展示外力搬運電荷克服電場斥力所做的微元梯形累積。'), ('Fig 21.4', '電感線圈自感磁通微元與反電動勢阻抗相圖', '自感儲能幾何', '橫軸電流 i，縱軸磁通量 Phi=L i；展示建立磁場過程中克服感應電動勢微元做功定積分。'), ('Fig 22.1', '畢奧-薩伐爾定律空間電流微元 dl x r_hat 叉積向量圖', '電磁三維向量空間', '電流微元 I dl、場點位置向量 r，展示右手螺旋定則決定的空間垂直磁場微元 dB 方向。'), ('Fig 22.2', '無窮長直導線三角角度代換 x = r_0 tan(theta) 掃描幾何圖', '解析幾何微元', '導線位置 x 與垂直距離 r_0，角度 theta 自 -pi/2 掃描至 +pi/2，定積分消除分母 4pi 產生 2pi r_0。'), ('Fig 22.3', '載流圓線圈軸線對稱磁場分量抵消與軸向疊加圖', '軸對稱電磁幾何', '圓線圈對稱微元產生的 dB 向量在徑向完全抵消，軸向分量 dB_x 累加，導出中心與軸線公式。'), ('Fig 22.4', '理想長螺線管矩形安培環路路徑積分閉合圖', '安培環路幾何', '穿過螺線管壁的矩形閉合迴路，外側磁場為零，兩垂直邊點積為零，管內邊積分產生 B = mu_0 n I。'), ('Fig 23.1', '均勻細棒繞質心 vs 繞端點轉動慣量微元分割圖', '剛體幾何微元', '細棒上的質量微元 dm = (M/L) dx，對比以中點為原點（[-L/2, L/2]）與以端點為原點（[0, L]）的 x^2 積分權重。'), ('Fig 23.2', '均勻圓盤同心圓環微元 dA = 2pi r dr 展開圖', '二維極對稱微元', '薄圓盤剖分為半徑為 r、厚度為 dr 的同心細圓環，展開為長方形條帶，轉動慣量微元 dI = r^2 dm。'), ('Fig 23.3', '實心球薄圓盤切片堆疊微元積分幾何圖', '三維立體幾何', '球體沿 z 軸切片為無窮多個半徑為 sqrt{R^2-z^2} 的薄圓盤，疊加積分嚴格推導 2/5 M R^2。'), ('Fig 23.4', '平行軸定理剛體轉動微元展開與質心抵消幾何圖', '剛體幾何定理', '任意剛體質心坐標系與偏心軸坐標系，展示展開式中線性項 int x_cm dm = 0 的質心對稱消除機制。'), ('Fig 24.1', '正弦曲線 sin(x) 多項式逐階逼近幾何曲線族', '級數收斂幾何', '原函數 sin(x) 與一階切線 x、三階多項式 x - x^3/6、五階多項式逐層貼合展開圖。'), ('Fig 24.2', '拉格朗日餘項夾擠區間與截斷誤差幾何界限圖', '誤差幾何分析', '曲線與泰勒多項式之間的差值陰影，標註介於展開點 a 與 x 之間的拉格朗日中值點 xi。'), ('Fig 24.3', '階乘對數 ln(n!) 直方圖階梯與曲線 ln(x) 定積分夾擠圖', '微元離散逼近', '高度為 ln(k) 的離散直方圖與平滑曲線 y = ln(x) 面積對比，直觀展示斯特靈公式的積分來源。'), ('Fig 24.4', '相對論因子 gamma 泰勒展開低速動能與一階修正曲線', '物理展開對比', '橫軸速度比 v/c，縱軸動能；展示低速時拋物線 1/2 mv^2 貼合，高速時四次方修正項劇烈抬升。'), ('Fig 25.1', '空間三維曲面 z = f(x, y) 及其切平面幾何切片圖', '多元空間幾何', '三維坐標系中的空間曲面，標註沿 x 軸切片的偏導斜率 f_x 與沿 y 軸切片的偏導斜率 f_y。'), ('Fig 25.2', '空間全微分微元 dz 在切平面上的線性投影矩形圖', '多元全微分幾何', '底面邊長 dx, dy 的矩形微元，在切平面上投影出高度增量 dz = f_x dx + f_y dy。'), ('Fig 25.3', '獨立測量誤差正交合成勾股幾何長方體圖', '誤差空間幾何', '兩互相獨立的測量不確定度分量 f_x sigma_x 與 f_y sigma_y 正交，合成總不確定度斜邊平方和開根號。'), ('Fig 25.4', '單擺測重力加速度 g(L, T) 誤差傳播等高線靈敏度圖', '實驗誤差靈敏度', '橫軸擺長 L，縱軸週期 T，等高線展示偏導權重，直觀顯示週期誤差的雙倍放大效應。'), ('Fig 26.1', '二維網格分割與曲頂柱體空間黎曼和體積圖', '多維積分黎曼和', '二維底面被切分為無窮多個小矩形 dA = dx dy，每個柱體高度為 f(x_i, y_j)，累積出空間體積。'), ('Fig 26.2', '極座標扇形微元 dA = r dr dtheta 幾何展開變形圖', '極座標面積微元', '同心圓環半徑 r 增量 dr，射線夾角 dtheta，扇形弧長 r dtheta，微元幾何近似為矩形 r dr dtheta。'), ('Fig 26.3', '直角坐標累次積分富比尼切片次序交換對比圖', '積分區域幾何', '同一平面積分區域，左圖先沿 y 軸垂直切片後沿 x 軸掃描，右圖先沿 x 軸水平切片後沿 y 軸掃描。'), ('Fig 26.4', '旋轉拋物面立體極座標切片體積二重積分圖', '旋轉體立體幾何', '拋物面 z = H - c r^2 在極座標下的二重積分，圓環體積微元 2pi r (H - c r^2) dr 累積為 1/2 pi R^2 H。'), ('Fig 27.1', '高斯二重極座標積分 I^2 平面旋轉曲面鐘形鐘乳石圖', '高維升維破局幾何', '三維空間曲面 z = e^{-(x^2+y^2)}，在極座標下為旋轉對稱鐘形體，體積微元 2pi r e^{-r^2} dr 積出 pi。'), ('Fig 27.2', '二項分佈直方圖向標準常態分佈鐘形曲線收斂極限圖', '中心極限定理幾何', 'n=10, 50, 200 時二項分佈長條圖逐步貼合標準鐘形曲線，係數 1/(sqrt{2pi} sigma) 完美閉環。'), ('Fig 27.3', '常態分佈 68-95-99.7% 經驗法則定積分標準區間陰影圖', '統計定積分幾何', '橫軸以標準差 sigma 為單位，標註 [-1, 1] 區間 68.26%、[-2, 2] 區間 95.44%、[-3, 3] 區間 99.74% 陰影面積。'), ('Fig 27.4', '馬克士威-波茲曼速率分佈曲線與阿瑞尼斯活化能尾部圖', '統計物理與化學相圖', '三種特徵速率 v_p < v_bar < v_rms 標註於鐘形曲線，右側高能尾部展示溫度升高時活化分子面積暴增。'), ('Fig 28.1', '正弦交流電瞬時電壓平方波形與平均值 1/2 對稱圖', '均方根微積分幾何', '正弦波 V_0 sin(omega t) 的平方波形 sin^2(omega t)，在 [0, V_0^2] 區間對稱對折，均值嚴格為 1/2。'), ('Fig 28.2', '台灣 110V 交流電有效值與瞬時峰值 155.6V 波形對照圖', '電工學工程圖', '標註標稱有效值水平線 110V，波形頂點穿刺至 155.6V，峰峰值高達 311V 的工程實用對照。'), ('Fig 28.3', '一維無限深勢阱量子波函數 psi_n(x) 與機率密度 |psi_n|^2 對照圖', '量子波函數機率幾何', '前三階駐波波函數 psi_n 與對應的機率密度分佈模平方，展示節點處粒子存在機率為零的量子特性。'), ('Fig 28.4', '【作用量與測不準大一統】拉格朗日作用量 S 與海森堡頻寬相長干涉圖', '量子微積分終極對偶', '展示經典作用量 S 達到極值處量子波函數相位同相相長疊加，動量空間波包 Delta p 與空間波包 Delta x 乘積受限於 hbar/2。')]
